Bench("AverageWordLength_Large", () => largeAnalyzer.AverageWordLength());
Bench("WordLengthHistogram_Small", () => smallAnalyzer.WordLengthHistogram());
Bench("WordLengthHistogram_Large", () => largeAnalyzer.WordLengthHistogram());
Bench("UniqueWordCount_Small", () => smallAnalyzer.UniqueWordCount());
Bench("UniqueWordCount_Large", () => largeAnalyzer.UniqueWordCount());

static void Bench(string name, Func<object?> action, int warmup = 100, int iterations = 10_000)
{
    // Warmup
    for (int i = 0; i < warmup; i++) action();

    // Measure allocations
    GC.Collect();
    GC.WaitForPendingFinalizers();
    GC.Collect();
    long allocBefore = GC.GetTotalAllocatedBytes(true);
    for (int i = 0; i < 100; i++) action();
    long allocAfter = GC.GetTotalAllocatedBytes(true);
    long allocPer = (allocAfter - allocBefore) / 100;

    // Measure time - take best of 5 runs to reduce noise
    double bestNs = double.MaxValue;
    for (int run = 0; run < 5; run++)
    {
        var sw = Stopwatch.StartNew();
        for (int i = 0; i < iterations; i++) action();
        sw.Stop();
        double ns = (double)sw.ElapsedTicks / Stopwatch.Frequency * 1_000_000_000 / iterations;
        if (ns < bestNs) bestNs = ns;
    }

    string timeStr = bestNs < 1000 ? $"{bestNs:F2} ns" : $"{bestNs / 1000:F2} us";
    string allocStr = allocPer == 0 ? "-" : $"{allocPer} B";
    Console.WriteLine($"{name,-35} {timeStr,12} {allocStr,12}");
}

